<?php
namespace App\Services\Football;use App\Contracts\Football\FootballDataProvider;use App\DTOs\Football\TeamGoalEvidence;use App\Models\Fixture;final class TeamGoalEvidenceBuilder{public function __construct(private FootballDataProvider $provider){}public function build(Fixture $fixture,bool $forHomeTeam,int $sample=10):TeamGoalEvidence{$fixture->loadMissing(['homeTeam','awayTeam','competition']);$team=$forHomeTeam?$fixture->homeTeam:$fixture->awayTeam;$opp=$forHomeTeam?$fixture->awayTeam:$fixture->homeTeam;$teamRows=array_slice($this->completed($this->provider->teamFixtures($team->provider_id,max(10,$sample))),0,$sample);$oppRows=array_slice($this->completed($this->provider->teamFixtures($opp->provider_id,max(10,$sample))),0,$sample);$teamVenue=array_values(array_filter($teamRows,fn($r)=>$this->isHome($r,$team->provider_id)===$forHomeTeam));$oppRelevantHome=!$forHomeTeam;$oppVenue=array_values(array_filter($oppRows,fn($r)=>$this->isHome($r,$opp->provider_id)===$oppRelevantHome));return new TeamGoalEvidence(min(count($teamRows),count($oppRows)),$this->rate($teamRows,fn($r)=>$this->gf($r,$team->provider_id)>0),$this->rate($teamVenue,fn($r)=>$this->gf($r,$team->provider_id)>0),$this->rate($oppRows,fn($r)=>$this->ga($r,$opp->provider_id)>0),$this->rate($oppVenue,fn($r)=>$this->ga($r,$opp->provider_id)>0),$this->rate($oppRows,fn($r)=>$this->ga($r,$opp->provider_id)===0),$this->rate($teamRows,fn($r)=>$this->gf($r,$team->provider_id)===0),false,false,(bool)$fixture->competition->high_variance);}private function completed(array $r):array{return array_values(array_filter($r,fn($x)=>isset($x['goals']['home'],$x['goals']['away'])&&($x['fixture']['status']['short']??'FT')==='FT'));}private function isHome(array $r,int $id):bool{return(int)($r['teams']['home']['id']??0)===$id;}private function gf(array $r,int $id):int{return$this->isHome($r,$id)?(int)$r['goals']['home']:(int)$r['goals']['away'];}private function ga(array $r,int $id):int{return$this->isHome($r,$id)?(int)$r['goals']['away']:(int)$r['goals']['home'];}private function rate(array $r,callable $f):float{return$r?count(array_filter($r,$f))/count($r):0.0;}}
